def countFancy(l, r):
    def is_good_number(x):
        # Strictly increasing or strictly decreasing digits (single digit is good)
        d = [int(c) for c in str(x)]
        if len(d) == 1:
            return True
        inc = True
        dec = True
        for i in range(1, len(d)):
            if d[i] <= d[i - 1]:
                inc = False
            if d[i] >= d[i - 1]:
                dec = False
        return inc or dec

    # good_sum[s] tells whether a digit sum s is itself a good number
    # (max digit sum is 9 * 16 = 144)
    good_sum = [False] * 200
    for s in range(1, 200):
        good_sum[s] = is_good_number(s)

    # memo for "free" suffixes: (remaining, digit_sum, last, state) -> count
    # last = 10 means no non-zero digit placed yet
    # state: 0 = single digit so far, 1 = strictly increasing,
    #        2 = strictly decreasing, 3 = broken (not monotone)
    memo = {}

    def step(last, state, d):
        # Returns new (last, state) after appending digit d
        if last == 10:
            if d == 0:
                return 10, 0       # still only leading zeros
            return d, 0            # first real digit
        if d > last:
            return d, (1 if state in (0, 1) else 3)
        if d < last:
            return d, (2 if state in (0, 2) else 3)
        return d, 3                # equal digits break strictness

    def free(rem, total, last, state):
        # Count ways to fill rem digits (any digits) so the final number is fancy
        if rem == 0:
            if last == 10:
                return 0           # the number 0 is not in range
            if state != 3 or good_sum[total]:
                return 1
            return 0
        key = (rem, total, last, state)
        if key in memo:
            return memo[key]
        res = 0
        for d in range(10):
            nl, ns = step(last, state, d)
            res += free(rem - 1, total + d, nl, ns)
        memo[key] = res
        return res

    def count_upto(n):
        # Number of fancy integers in [1, n]
        if n <= 0:
            return 0
        digits = [int(c) for c in str(n)]
        m = len(digits)
        res = 0
        total = 0
        last = 10
        state = 0
        # Walk along the tight prefix of n; at each position try smaller digits
        for pos in range(m):
            for d in range(digits[pos]):
                nl, ns = step(last, state, d)
                res += free(m - pos - 1, total + d, nl, ns)
            last, state = step(last, state, digits[pos])
            total += digits[pos]
        # Finally n itself
        if state != 3 or good_sum[total]:
            res += 1
        return res

    return count_upto(r) - count_upto(l - 1)
